INSERT INTO landing_revisions(id,label,chrome,seo) VALUES ('40000000-0000-4000-8000-000000000001','Landing hiện tại — cần duyệt nội dung và quyền ảnh','{"announcement":{"lead":"Giải pháp điện mặt trời:","body":" Tư vấn theo nhu cầu và hiện trạng công trình.","actionLabel":"Đặt lịch khảo sát","actionHref":"/khao-sat/","enabled":true},"brand":{"label":"Lúa Xanh Đồng Bằng - Trang chủ","lines":["LÚA XANH","ĐỒNG BẰNG"],"href":"/","logoSlot":"chrome.logo"},"navigation":{"label":"Điều hướng chính","items":[{"label":"Trang chủ","href":"/"},{"label":"Giải pháp","href":"/#giai-phap","overviewLabel":"Tổng quan giải pháp","children":[{"label":"Giải pháp hộ gia đình","href":"/giai-phap/ho-gia-dinh/"},{"label":"Giải pháp hộ kinh doanh vừa & nhỏ","href":"/giai-phap/ho-kinh-doanh/"},{"label":"Giải pháp doanh nghiệp & công nghiệp","href":"/giai-phap/doanh-nghiep/"}]},{"label":"Dịch vụ","href":"/#dich-vu","overviewLabel":"Tổng quan dịch vụ","children":[{"label":"EPC trọn gói","href":"/dich-vu/epc-tron-goi/"},{"label":"Phân phối và cung ứng thiết bị điện mặt trời","href":"/dich-vu/cung-ung-thiet-bi/"},{"label":"Các mô hình tài chính/đầu tư","href":"/dich-vu/mo-hinh-tai-chinh/"}]},{"label":"Dự án","href":"/du-an/"},{"label":"Thiết bị","href":"/thiet-bi/"}],"callToAction":{"label":"Khảo sát","href":"/khao-sat/"}},"conversion":{"surveyHref":"/khao-sat/","phoneHref":null,"zaloHref":null},"footer":{"columns":[{"title":"Giải pháp & Quy trình","items":[{"label":"Giải pháp theo nhu cầu","href":"/#giai-phap"},{"label":"Đặt lịch khảo sát","href":"/khao-sat/"}]},{"title":"Hệ thống & Dịch vụ","items":[{"label":"Thiết bị điện mặt trời","href":"/thiet-bi/"},{"label":"Dự án thực tế","href":"/du-an/"},{"label":"Câu hỏi thường gặp","href":"/#faq"}]},{"title":"Liên hệ","items":[{"label":"13 Đồng Khởi, Phường Ninh Kiều, TP. Cần Thơ"},{"label":"lienhe@luaxanhdongbang.vn","href":"mailto:lienhe@luaxanhdongbang.vn"},{"label":"Thứ 2 - Thứ 7: 07:30 - 18:00"}]}],"note":"Bản demo giao diện · Ảnh dự án, sản phẩm, đối tác và thông tin liên hệ cần xác minh trước khi sử dụng thực tế."}}'::jsonb,'{"title":"Giải pháp điện mặt trời cho gia đình và doanh nghiệp","description":"Tìm hiểu giải pháp điện mặt trời của Lúa Xanh Đồng Bằng: khảo sát, thiết kế, thi công, vận hành và các công trình đã triển khai.","requestedIndexable":false}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','hero',0,true,'{"title":"ƯƠM MẦM\nNĂNG LƯỢNG","tagline":"Tận tâm · Đồng hành · Chất lượng","description":"Lúa Xanh Đồng Bằng cung cấp giải pháp điện mặt trời từ khảo sát, thiết kế, thi công đến vận hành và bảo trì dài hạn. Mỗi hệ thống được xây dựng dựa trên nhu cầu sử dụng điện, điều kiện công trình và hiệu quả đầu tư thực tế.","primaryAction":{"label":"KHẢO SÁT MIỄN PHÍ","href":"/khao-sat/"},"secondaryAction":{"label":"DỰ ÁN THỰC TẾ","href":"/du-an/"},"imageAlt":"Hình minh họa thi công hệ thống điện mặt trời","imageSlot":"hero.image","bottomImageSlot":"hero.bottomImage"}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','partners',1,true,'{"title":"Đối Tác\nChiến Lược","brandsLabel":"Đối tác trong mẫu thiết kế","brands":[{"name":"AIKO","emphasis":false},{"name":"BYD","emphasis":true},{"name":"HUAWEI","emphasis":false},{"name":"solis","emphasis":true},{"name":"SMA","emphasis":false},{"name":"LONGi","emphasis":true},{"name":"CanadianSolar","emphasis":false},{"name":"SUNGROW","emphasis":false},{"name":"AESOLAR","emphasis":false}]}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','services',2,true,'{"heading":"CHÚNG TÔI LÀM GÌ","introduction":"Công ty TNHH Lúa Xanh Đồng Bằng được thành lập với định vị là đối tác thực thi toàn diện trong lĩnh vực điện mặt trời áp mái. Lúa Xanh Đồng Bằng không chỉ là nhà thầu EPC, chúng tôi cung cấp giải pháp tư vấn pháp lý trọn gói. Đội ngũ chuyên trách của chúng tôi am hiểu sâu sắc quy định của EVN, sẵn sàng đại diện chủ đầu tư xử lý toàn bộ các thủ tục phức tạp.","items":[{"title":"EPC trọn gói","href":"/dich-vu/epc-tron-goi/","points":["Tư Vấn & Khảo Sát Hiện Trạng","Thiết kế kỹ thuật chuyên sâu","Thi công & Lắp đặt chuẩn hóa","Cung Cấp Thiết bị","Vận Hành & Bảo Trì (O&M)"],"key":"epc","imageSlot":"services.epc.image"},{"title":"Phân phối và cung ứng thiết bị điện mặt trời","href":"/dich-vu/cung-ung-thiet-bi/","points":["Tấm pin năng lượng mặt trời","Bộ biến tần","Hệ khung & phụ kiện lắp đặt"],"key":"equipment-supply","imageSlot":"services.equipment-supply.image"},{"title":"Các mô hình tài chính/đầu tư","href":"/dich-vu/mo-hinh-tai-chinh/","points":["Tự sản – tự tiêu","Cho thuê thiết bị","DPPA / bán điện trực tiếp"],"key":"investment","imageSlot":"services.investment.image"}]}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','solutions',3,true,'{"heading":"GIẢI PHÁP CHUYÊN BIỆT\nCHO TỪNG NHÓM KHÁCH HÀNG","introduction":"Chọn nhóm khách hàng phù hợp để xem những thông tin cần cân nhắc trước khi khảo sát.","items":[{"title":"Giải pháp hộ gia đình","text":"Cân đối theo hóa đơn điện, thói quen sử dụng và điều kiện mái nhà.","icon":"⌂","href":"/giai-phap/ho-gia-dinh/","actionLabel":"Tìm hiểu giải pháp ⟶","key":"household","imageSlot":"solutions.household.image"},{"title":"Giải pháp hộ kinh doanh vừa & nhỏ","text":"Xem xét giờ vận hành, phụ tải ban ngày và diện tích mái trước khi đề xuất hệ thống.","icon":"⚙","href":"/giai-phap/ho-kinh-doanh/","actionLabel":"Tìm hiểu giải pháp ⟶","key":"small-business","imageSlot":"solutions.small-business.image"},{"title":"Giải pháp doanh nghiệp & công nghiệp","text":"Khảo sát phụ tải, mặt bằng, yêu cầu kỹ thuật và quy trình phối hợp của công trình.","icon":"▤","href":"/giai-phap/doanh-nghiep/","actionLabel":"Tìm hiểu giải pháp ⟶","key":"enterprise","imageSlot":"solutions.enterprise.image"}]}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','whyUs',4,true,'{"heading":"VÌ SAO CHỌN LÚA XANH ĐỒNG BẰNG","banner":"GIẢI PHÁP PHÙ HỢP · VẬN HÀNH BỀN VỮNG · GIÁ TRỊ DÀI HẠN","paragraphs":["Lúa Xanh Đồng Bằng lấy an toàn kỹ thuật, chất lượng triển khai và hiệu quả sử dụng thực tế làm nền tảng cho mỗi công trình. Chúng tôi không áp dụng một cấu hình cố định, mà cân nhắc đặc điểm sử dụng điện, điều kiện công trình và mục tiêu của từng khách hàng.","Thông qua quy trình làm việc rõ ràng, thiết bị phù hợp và hỗ trợ sau bàn giao, Lúa Xanh Đồng Bằng hướng đến những hệ thống vận hành ổn định, dễ quản lý và mang lại giá trị lâu dài."],"images":[{"alt":"Hình minh họa hệ thống điện áp mái","key":"primary","imageSlot":"whyUs.primary.image"},{"alt":"Hình minh họa hệ thống điện mặt trời","key":"secondary","imageSlot":"whyUs.secondary.image"},{"alt":"Hình minh họa tấm pin mặt trời","key":"panel","imageSlot":"whyUs.panel.image"}]}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','featuredProjects',5,true,'{"heading":"DỰ ÁN TIÊU BIỂU","viewAllLabel":"XEM TẤT CẢ CÁC DỰ ÁN ⟶","viewAllHref":"/du-an/"}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','testimonials',6,false,'{"title":"Chia sẻ từ khách hàng","description":"Trải nghiệm thực tế sẽ được cập nhật sau khi có nội dung được khách hàng xác nhận.","items":[]}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','equipmentOffer',7,true,'{"heading":"THIẾT BỊ & GIẢI PHÁP LƯU TRỮ","viewAllLabel":"Xem các nhóm thiết bị ⟶","viewAllHref":"/thiet-bi/"}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','faq',8,true,'{"heading":"CÂU HỎI THƯỜNG GẶP","introduction":"Giải đáp các băn khoăn phổ biến của chủ nhà và chủ doanh nghiệp trước khi quyết định đầu tư hệ thống điện mặt trời.","imageAlt":"Hình minh họa trang trại điện mặt trời","actionLabel":"Tìm hiểu khảo sát","actionHref":"/khao-sat/","questions":[{"title":"Hệ thống tấm pin mặt trời có bền không?","text":"Tấm pin thường được nhà sản xuất công bố tuổi thọ khoảng 25–30 năm. Tuổi thọ biến tần và thời hạn bảo hành phụ thuộc từng dòng thiết bị; việc lắp đặt và bảo trì đúng cách giúp hệ thống vận hành ổn định."},{"title":"Mất bao lâu để hệ thống hoàn vốn?","text":"Thời gian hoàn vốn phụ thuộc vốn đầu tư, sản lượng điện, mức sử dụng điện ban ngày và giá điện. Chúng tôi sẽ ước tính riêng cho công trình sau khi khảo sát hiện trạng."},{"title":"Có thể lắp đặt trên mái nhà cũ không?","text":"Có thể, nhưng cần kiểm tra kỹ lưỡng kết cấu mái. Chúng tôi sẽ đánh giá độ bền và đề xuất giải pháp phù hợp trong khảo sát miễn phí."}],"imageSlot":"faq.image"}'::jsonb);
INSERT INTO landing_sections(revision_id,section_key,position,enabled,content) VALUES ('40000000-0000-4000-8000-000000000001','contact',9,true,'{"heading":["MUỐN BIẾT NHÀ BẠN CÓ PHÙ HỢP","ĐỂ LẮP ĐẶT KHÔNG?"],"description":"Liên hệ với chúng tôi hôm nay. Đội kỹ thuật sẽ đến tận nơi trong 48 giờ.","actionLabel":"Hẹn lịch khảo sát miễn phí","actionHref":"/khao-sat/"}'::jsonb);
